const chatId = String($json.message?.chat?.id || '');
const text = ($json.message?.text || '').trim();
const m = text.match(/^\/remind\s+(\S+)\s+(\S+)\s+(\S+)/i);

if (!chatId) throw new Error('No chat id in Telegram payload');

if (!m) {
  return {
    json: {
      chatId,
      sendTo: 'example@client.com',
      subject: 'Payment reminder',
      message: '',
      ackText: 'Usage: /remind <email> <amount> <dueDate>'
    }
  };
}

const [_, email, amount, dueDate] = m;
return {
  json: {
    chatId,
    sendTo: email,
    subject: `Payment reminder - due ${dueDate}`,
    message: [
      'Hi,',
      '',
      `This is a friendly reminder for the pending payment of ${amount}.`,
      `Due date: ${dueDate}.`,
      '',
      'Thanks.'
    ].join('\n'),
    ackText: `Reminder prepared for ${email}`
  }
};
